    year, month = start.year, start.month
    while (year, month) <= (limit.year, limit.month):
        if month in s.months:
            first_weekday, last = calendar.monthrange(year, month)
            # calendar weekday: Monday is 0; convert to Sunday is 0.
            first_weekday = (first_weekday + 1) % 7
            for day in range(1, last + 1):
                date = datetime.date(year, month, day)
                if date < first_day:
                    continue
                if date > limit.date():
                    return None
                weekday = (first_weekday + day - 1) % 7
                if not _day_allowed(s, year, month, day, last, weekday):
                    continue
                for hour in s.hours:
                    for minute in s.minutes:
                        run = datetime.datetime(year, month, day, hour, minute)
                        if run < start:
                            continue
                        if run > limit:
                            return None
                        return run
        month += 1
        if month > 12:
            year, month = year + 1, 1
    return None
